<?php
$appPage='beneficiaries';$appTitle='Beneficiaries';require __DIR__.'/../includes/customer_header.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$name=trim($_POST['display_name']??'');$number=strtoupper(trim($_POST['account_number']??''));if($name===''||mb_strlen($name)>100)throw new InvalidArgumentException('Enter a beneficiary name.');$check=$pdo->prepare('SELECT account_id,user_id FROM accounts WHERE account_number=?');$check->execute([$number]);$destination=$check->fetch();if(!$destination)throw new InvalidArgumentException('Destination account was not found.');if((int)$destination['user_id']===$customerId)throw new InvalidArgumentException('You cannot add your own account.');$stmt=$pdo->prepare('INSERT INTO beneficiaries (user_id,display_name,destination_account_number) VALUES (?,?,?) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),status=\'active\'');$stmt->execute([$customerId,$name,$number]);$success='Beneficiary saved.';}catch(Throwable $e){$error=$e->getMessage();}}
$stmt=$pdo->prepare('SELECT * FROM beneficiaries WHERE user_id=? AND status=\'active\' ORDER BY display_name');$stmt->execute([$customerId]);$beneficiaries=$stmt->fetchAll();
?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif?><div class="app-grid"><section class="panel span-5"><h2>Add beneficiary</h2><form method="post" class="form-grid"><?=csrfField()?><div class="field full"><label for="display_name">Display name</label><input id="display_name" name="display_name" maxlength="100" required></div><div class="field full"><label for="account_number">Valtoria account number</label><input id="account_number" name="account_number" maxlength="20" required></div><div class="field full"><button class="button button-primary">Save beneficiary</button></div></form></section><section class="panel span-7"><h2>Saved beneficiaries</h2><?php if(!$beneficiaries):?><div class="empty">No beneficiaries saved.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Account</th><th>Added</th></tr></thead><tbody><?php foreach($beneficiaries as $b):?><tr><td><?=e($b['display_name'])?></td><td><?=e($b['destination_account_number'])?></td><td><?=e($b['created_at'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section></div><?php require __DIR__.'/../includes/customer_footer.php';?>
